// Package config contains the process configuration for the IAM service.
package config

import (
	"errors"
	"fmt"
	"os"
	"strconv"
	"time"
)

// Config is the configuration shared by the service dependencies.
type Config struct {
	Address           string
	Issuer            string
	HMACSecret        string
	AccessTTL         time.Duration
	RefreshTTL        time.Duration
	ReadTimeout       time.Duration
	WriteTimeout      time.Duration
	IdleTimeout       time.Duration
	ShutdownTimeout   time.Duration
	LoginRateLimit    int
	RegisterRateLimit int
}

// Load reads configuration from environment variables and validates it.
func Load() (Config, error) {
	c := Config{
		Address:           envOr("IAM_ADDR", ":8080"),
		Issuer:            envOr("IAM_ISSUER", "benchmark.local/iam"),
		HMACSecret:        os.Getenv("IAM_HMAC_SECRET"),
		AccessTTL:         durationOr("IAM_ACCESS_TTL", time15Minutes),
		RefreshTTL:        durationOr("IAM_REFRESH_TTL", 30*24*time.Hour),
		ReadTimeout:       durationOr("IAM_READ_TIMEOUT", 5*time.Second),
		WriteTimeout:      durationOr("IAM_WRITE_TIMEOUT", 10*time.Second),
		IdleTimeout:       durationOr("IAM_IDLE_TIMEOUT", 60*time.Second),
		ShutdownTimeout:   durationOr("IAM_SHUTDOWN_TIMEOUT", 10*time.Second),
		LoginRateLimit:    intOr("IAM_LOGIN_RATE_LIMIT", 10),
		RegisterRateLimit: intOr("IAM_REGISTER_RATE_LIMIT", 5),
	}
	if err := c.Validate(); err != nil {
		return Config{}, err
	}
	return c, nil
}

const time15Minutes = 15 * time.Minute

// Validate checks security-sensitive and server timing settings.
func (c Config) Validate() error {
	if len([]byte(c.HMACSecret)) < 32 {
		return errors.New("IAM_HMAC_SECRET must be at least 32 bytes")
	}
	if c.Address == "" {
		return errors.New("IAM_ADDR must not be empty")
	}
	if c.Issuer == "" {
		return errors.New("IAM_ISSUER must not be empty")
	}
	for name, value := range map[string]time.Duration{
		"access TTL": c.AccessTTL, "refresh TTL": c.RefreshTTL,
		"read timeout": c.ReadTimeout, "write timeout": c.WriteTimeout,
		"idle timeout": c.IdleTimeout, "shutdown timeout": c.ShutdownTimeout,
	} {
		if value <= 0 {
			return fmt.Errorf("%s must be greater than zero", name)
		}
	}
	if c.LoginRateLimit <= 0 || c.RegisterRateLimit <= 0 {
		return errors.New("rate limits must be greater than zero")
	}
	return nil
}

func envOr(name, fallback string) string {
	if value := os.Getenv(name); value != "" {
		return value
	}
	return fallback
}

func durationOr(name string, fallback time.Duration) time.Duration {
	value := os.Getenv(name)
	if value == "" {
		return fallback
	}
	parsed, err := time.ParseDuration(value)
	if err != nil {
		return -1
	}
	return parsed
}

func intOr(name string, fallback int) int {
	value := os.Getenv(name)
	if value == "" {
		return fallback
	}
	parsed, err := strconv.Atoi(value)
	if err != nil {
		return -1
	}
	return parsed
}
package domain

import "errors"

// ErrorKind identifies the stable class of a domain failure.
type ErrorKind string

const (
	ErrorNotFound     ErrorKind = "not_found"
	ErrorConflict     ErrorKind = "conflict"
	ErrorInvalid      ErrorKind = "invalid"
	ErrorUnauthorized ErrorKind = "unauthorized"
)

var (
	ErrNotFound     = &DomainError{Kind: ErrorNotFound}
	ErrConflict     = &DomainError{Kind: ErrorConflict}
	ErrInvalid      = &DomainError{Kind: ErrorInvalid}
	ErrUnauthorized = &DomainError{Kind: ErrorUnauthorized}
)

// DomainError is a typed error with a stable kind suitable for mapping to an
// HTTP error envelope. Details are optional and should not contain secrets.
type DomainError struct {
	Kind  ErrorKind
	Msg   string
	Cause error
}

func (e *DomainError) Error() string {
	if e.Msg != "" {
		return e.Msg
	}
	return string(e.Kind)
}

func (e *DomainError) Unwrap() error { return e.Cause }

// Is lets callers use errors.Is while retaining the more specific Kind.
func (e *DomainError) Is(target error) bool {
	other, ok := target.(*DomainError)
	return ok && e.Kind == other.Kind
}

// NewError annotates a stable error kind with a safe, human-readable message.
func NewError(kind ErrorKind, message string) error {
	return &DomainError{Kind: kind, Msg: message}
}

func IsKind(err error, kind ErrorKind) bool {
	var domainErr *DomainError
	return errors.As(err, &domainErr) && domainErr.Kind == kind
}

func IsNotFound(err error) bool     { return IsKind(err, ErrorNotFound) }
func IsConflict(err error) bool     { return IsKind(err, ErrorConflict) }
func IsInvalid(err error) bool      { return IsKind(err, ErrorInvalid) }
func IsUnauthorized(err error) bool { return IsKind(err, ErrorUnauthorized) }
